def maps(s):
    from scipy.optimize import least_squares
    (u, v) = (s['panel_a'][k] for k in ('u', 'v'))
    ok = np.linalg.norm(v, axis=1) < 5
    (u, v) = (u[ok], v[ok])
    w = np.roll(u, -1, axis=1)
    (off, scale) = np.array([fit(aff(u[:, j]), v[:, j] - 0.32 * (u[:, j] - 1) * w[:, j] - 0.16 * u[:, j] ** 3) for j in range(4)]).T

    def f(z):
        return off + scale * z + 0.32 * (z - 1) * np.roll(z, -1, axis=-1) + 0.16 * z ** 3

    def inv(x):
        return np.array([least_squares(lambda z: f(z) - h, (h - off) / scale, gtol=1e-12).x for h in x])

    def op(panel, k, fn, p, lo, hi):
        (u, v) = (panel['u'], panel[k])

        def res(p):
            h = aff(fn(u, p))
            return (h @ fit(h, v) - v).ravel()
        p = least_squares(res, p, bounds=(lo, hi), gtol=1e-12).x
        c = fit(aff(fn(u, p)), v)
        return lambda x: aff(fn(x, p)) @ c
    b = op(s['panel_b'], 'v', lambda x, p: np.cos(p[0] * x), [2.6], [2], [3.2])
    c = op(s['panel_c'], 'v1', lambda x, p: x / (1 + p[0] * abs(x) ** p[1]) ** p[2], [0.62, 1.07, 1.57], [0.1, 0.1, 0.2], [4, 4, 5])
    d = op(s['panel_c'], 'v2', lambda x, p: np.logaddexp(0, p[0] * x + p[1]), [2.2, 0], [1, -2], [4, 2])
    return (f, inv, b, c, d)

def _features(study, x):
    (_, inv, op, _, _) = maps(study)
    z = inv(x)
    return (op(z), np.cos(2.6 * z))

def pool(s, x, depth=2):
    (f, inv, b, c, d) = maps(s)
    z = inv(x)
    D = {'x': x, 'z': z, 'a': f(x)}
    new = D.copy()
    for _ in range(depth):
        new = {k + n: fn(X) for (n, X) in new.items() for (k, fn) in zip('bcd', (b, c, d))}
        D.update(new)
    return D

def score(h, v):
    p = np.linalg.pinv(h)
    e = v - h @ (p @ v)
    return (np.sqrt(np.mean(e ** 2)), np.sqrt(np.mean((e / (1 - (h * p.T).sum(1))[:, None]) ** 2)))
